import os
import json
import time
from datetime import date, timedelta, datetime
from urllib.parse import quote_plus
from urllib.request import Request, urlopen

BASE_URL = "https://api.github.com/search/issues"
HEADERS = {
    "Accept": "application/vnd.github+json",
    "User-Agent": "codex-cli",
}
TOKEN = os.getenv("GITHUB_TOKEN") or os.getenv("GH_TOKEN")
if TOKEN:
    HEADERS["Authorization"] = f"Bearer {TOKEN}"


def request_json(url):
    req = Request(url, headers=HEADERS)
    with urlopen(req) as resp:
        data = json.loads(resp.read().decode("utf-8"))
        headers = resp.headers
    return data, headers


def search_total(query):
    url = f"{BASE_URL}?q={quote_plus(query)}&per_page=1&page=1"
    data, _ = request_json(url)
    return data.get("total_count", 0)


def search_items(query):
    items = []
    page = 1
    while True:
        url = f"{BASE_URL}?q={quote_plus(query)}&per_page=100&page={page}"
        data, _ = request_json(url)
        batch = data.get("items", [])
        items.extend(batch)
        if len(batch) < 100:
            break
        page += 1
        if page > 10:
            break
        time.sleep(0.2)
    return items


def fetch_range(base_query, field, start_date, end_date):
    query = f"{base_query} {field}:{start_date}..{end_date}"
    total = search_total(query)
    if total > 1000:
        if start_date == end_date:
            raise RuntimeError(f"Too many results for {query}")
        mid = start_date + (end_date - start_date) // 2
        left = fetch_range(base_query, field, start_date, mid)
        right = fetch_range(base_query, field, mid + timedelta(days=1), end_date)
        return left + right
    return search_items(query)


def parse_dt(value):
    if not value:
        return None
    if value.endswith("Z"):
        value = value[:-1] + "+00:00"
    return datetime.fromisoformat(value)


start = date(2024, 12, 1)
end = date(2024, 12, 31)

# Pull requests
base_pr = "repo:cli/cli is:pr"
pr_items = fetch_range(base_pr, "created", start, end)

merged_items = fetch_range(base_pr + " is:merged", "created", start, end)

closed_not_merged_query = f"{base_pr} is:closed -is:merged created:{start}..{end}"
closed_not_merged = search_total(closed_not_merged_query)

# Average merge time in days
merge_durations = []
for item in merged_items:
    created_at = parse_dt(item.get("created_at"))
    closed_at = parse_dt(item.get("closed_at"))
    if created_at and closed_at:
        delta = closed_at - created_at
        merge_durations.append(delta.total_seconds() / 86400)

avg_merge_days = round(sum(merge_durations) / len(merge_durations), 1) if merge_durations else 0.0

# Top contributor
author_counts = {}
for item in pr_items:
    user = item.get("user") or {}
    login = user.get("login") or "unknown"
    author_counts[login] = author_counts.get(login, 0) + 1

top_contributor = ""
if author_counts:
    top_contributor = sorted(author_counts.items(), key=lambda x: (-x[1], x[0]))[0][0]

# Issues
base_issue = "repo:cli/cli is:issue"
issue_items = fetch_range(base_issue, "created", start, end)

bug_issues = 0
for item in issue_items:
    labels = item.get("labels") or []
    if any("bug" in (lbl.get("name") or "").lower() for lbl in labels):
        bug_issues += 1

closed_bug_items = fetch_range(base_issue + " is:closed", "closed", start, end)
resolved_bugs = 0
for item in closed_bug_items:
    labels = item.get("labels") or []
    if any("bug" in (lbl.get("name") or "").lower() for lbl in labels):
        resolved_bugs += 1

report = {
    "pr": {
        "total": len(pr_items),
        "merged": len(merged_items),
        "closed": closed_not_merged,
        "avg_merge_days": avg_merge_days,
        "top_contributor": top_contributor,
    },
    "issue": {
        "total": len(issue_items),
        "bug": bug_issues,
        "resolved_bugs": resolved_bugs,
    },
}

with open("/app/report.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2, sort_keys=False)

print("Wrote /app/report.json")
